  fs14.mkdirSync(inputDir, { recursive: true });
  const mainFileName = path15.basename(mainFile);
  const localMainPath = path15.join(inputDir, mainFileName);
  await downloadFile(mainFile, localMainPath, verbose);
  await processImports2(localMainPath, baseRepoUrl, inputDir, verbose);
